num_golfers = 32
num_groups = 8
group_size = 4
num_weeks = 6

# Verify constraints
# 1. Each week, each group has exactly 4 golfers
for w in range(num_weeks):
    for g in range(num_groups):
        count = sum(1 for p in range(num_golfers) if solution[w*32 + p] == g)
        if count != group_size:
            print(f"Week {w}, Group {g}: {count} golfers (expected {group_size})")

# 2. No pair of golfers is in the same group more than once
pair_count = {}
for w in range(num_weeks):
    for p1 in range(num_golfers):
        for p2 in range(p1+1, num_golfers):
            if solution[w*32 + p1] == solution[w*32 + p2]:
                key = (p1, p2)
                pair_count[key] = pair_count.get(key, 0) + 1

violations = [(k, v) for k, v in pair_count.items() if v > 1]
if violations:
    print(f"Violations: {violations[:10]}")
else:
    print("All constraints satisfied!")
    print(f"Total pairs that played together: {len(pair_count)}")
    print(f"Total possible pairs: {num_golfers * (num_golfers - 1) // 2}")
